import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0])
    idx = 1

    ans = 0
    speed = 0
    limit = 10**9
    overtake_allowed = True

    # stack of active speed limits (values), with lazy removal
    limits = []
    # stack of active "no overtake" signs; each entry is a marker
    no_overtake = []

    for _ in range(n):
        t = int(data[idx]); idx += 1
        if t == 1:
            speed = int(data[idx]); idx += 1
        elif t == 2:
            if not overtake_allowed:
                ans += len(no_overtake)
                no_overtake.clear()
                overtake_allowed = True
        elif t == 3:
            s = int(data[idx]); idx += 1
            limits.append(s)
            limit = s
        elif t == 4:
            overtake_allowed = True
            no_overtake.clear()
        elif t == 5:
            limits.clear()
            limit = 10**9
        elif t == 6:
            if overtake_allowed:
                overtake_allowed = False
                no_overtake.append(1)
            else:
                no_overtake.append(1)

        # check speed violation against current effective limit
        if limits:
            while limits and limits[-1] < speed:
                limits.pop()
                ans += 1
            if limits:
                limit = limits[-1]
            else:
                limit = 10**9
        else:
            limit = 10**9

    print(ans)

if __name__ == "__main__":
    main()
